var ph = PhaseManager.get_current_phase_instance()
var got: Array = []
var ids := {}
for a in ph.pending_assignments:
	got.append("%s>%s>%s" % [a.weapon_id, a.target_unit_id, ",".join(a.get("model_ids", []))])
	ids[a.weapon_id] = true
tree.root.set_meta("t06_declared", got)
return ids.size()

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var main = tree.root.get_node("Main")
tree.root.set_meta("t06_cam", [main.view_zoom, main.view_offset])
if d.is_active() or d.visible:
	return "dock already up"
if tree.root.get_node_or_null("WeaponOrderDialog") != null:
	return "a WeaponOrderDialog window exists"
if main.get_node_or_null("WeaponOrderPanel") != null:
	return "the old disconnected /root/Main/WeaponOrderPanel stub is still installed"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
if str(ph.resolution_state.get("phase", "")) != "awaiting_weapon_order":
	return "phase not in the weapon-order step: %s" % str(ph.resolution_state.get("phase", ""))
if not (d.is_active() and d.is_ordering() and d.visible):
	return "dock not in its ordering step (state %s)" % d.state
if sc.declaration_box.visible:
	return "declaration widgets still showing"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var rows = d.queue_box.get_children()
if rows.size() != 3:
	return "queue rows: %d" % rows.size()
for i in range(3):
	var r = d.queue_box.get_node_or_null("QueueRow%d" % i)
	if r == null or r.get_node_or_null("Up%d" % i) == null or r.get_node_or_null("Down%d" % i) == null:
		return "row %d has no reorder arrows" % i
	if not str(r.get_node("RowText").text).contains("Witchseekers"):
		return "row %d does not name its target: %s" % [i, r.get_node("RowText").text]
if not (d.queue_box.get_node("QueueRow0/Up0").disabled and not d.queue_box.get_node("QueueRow0/Down0").disabled):
	return "first row arrows wrong"
if d.primary_button.text != "Roll to Hit ▶" or not d.primary_button.visible or d.primary_button.disabled:
	return "Start Sequence (Roll to Hit) missing: %s" % d.primary_button.text
if not d.fast_button.visible or not str(d.fast_button.text).begins_with("Fast Roll All"):
	return "Fast Roll All missing: %s" % d.fast_button.text
var c = d.get_node_or_null("DockCancelButton")
if c == null or not c.is_visible_in_tree() or c.disabled or c.text != "◀ Back to Targets (Esc)":
	return "Back to Targets (Esc) missing or disabled"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var vp: Rect2 = d.get_viewport_rect()
return d.get_global_rect().position.x / vp.size.x

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var board: Rect2 = SceneRefs.board_screen_rect()
if not board.has_area():
	return "no board rect"
return d.get_global_rect().intersects(board)

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var main = tree.root.get_node("Main")
var r: Rect2 = d.get_global_rect()
var hr: Rect2 = main.get_node("HUD_Right").get_global_rect()
if not hr.encloses(r):
	return "panel spills out of the right HUD column: %s vs %s" % [str(r), str(hr)]
for p in ["PhaseActionButton", "HUD_Bottom", "PhaseStrip", "GameLogPanel"]:
	var n = main.get_node_or_null(p)
	if n != null and n is Control and n.is_visible_in_tree() and n.get_global_rect().intersects(r):
		return "panel overlaps %s" % p
for s in d.get_parent().get_children():
	if s != d and s is Control and s.is_visible_in_tree() and s.get_global_rect().intersects(r):
		return "panel overlaps sibling %s" % s.name
return "ok"

for w in tree.root.get_children():
	if w is Window and w.visible and str(w.name).contains("WeaponOrder"):
		return "modal window %s" % w.name
return tree.root.get_node_or_null("WeaponOrderDialog") == null

var main = tree.root.get_node("Main")
var cam: Array = tree.root.get_meta("t06_cam", [])
return cam.size() == 2 and is_equal_approx(main.view_zoom, cam[0]) and main.view_offset.is_equal_approx(cam[1])

var hov = tree.root.get_viewport().gui_get_hovered_control()
if hov != null:
	return "a Control swallows the mouse over the board: %s" % hov.get_path()
var lv = tree.root.get_node_or_null("Main/BoardRoot/LOSLineVisual")
if lv == null or lv.current_line == null or str(lv.current_line.target_id) != "U_WITCHSEEKERS_C" or not lv.get_node("Line").visible:
	return "the board did not react to the hover (no shooter-to-target LoS line)"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
if not ph.pending_assignments.is_empty() or ph.confirmed_assignments.size() != 3:
	return "the click changed the declaration (%d pending, %d confirmed)" % [ph.pending_assignments.size(), ph.confirmed_assignments.size()]
if not d.is_ordering() or str(ph.resolution_state.get("phase", "")) != "awaiting_weapon_order":
	return "the click left the weapon-order step"
if not str(d.status_label.text).contains("Esc (Back to Targets)"):
	return "no hint in the panel: %s" % d.status_label.text
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
if sc.active_shooter_id != "U_BATTLEWAGON_A" or ph.active_shooter_id != "U_BATTLEWAGON_A":
	return "shooter switched (%s / %s)" % [sc.active_shooter_id, ph.active_shooter_id]
if tree.root.get_node_or_null("UnitSwitchConfirmDialog") != null:
	return "a unit-switch dialog opened"
return "ok" if d.is_ordering() else "dock left its ordering step"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
var want: Array = tree.root.get_meta("t06_declared", [])
var got: Array = []
for a in ph.pending_assignments:
	got.append("%s>%s>%s" % [a.weapon_id, a.target_unit_id, ",".join(a.get("model_ids", []))])
if d.is_active() or d.visible:
	return "dock still up (state %s)" % d.state
if not sc.declaration_box.visible:
	return "declaration widgets not back"
if got != want:
	return "declaration changed: %s vs %s" % [str(got), str(want)]
if not ph.confirmed_assignments.is_empty() or not ph.resolution_state.is_empty():
	return "phase still holds a confirmed shot: %s" % str(ph.resolution_state)
if sc.active_shooter_id != "U_BATTLEWAGON_A" or ph.active_shooter_id != "U_BATTLEWAGON_A":
	return "shooter deselected (%s / %s)" % [sc.active_shooter_id, ph.active_shooter_id]
if "U_BATTLEWAGON_A" in ph.units_that_shot or GameState.get_unit("U_BATTLEWAGON_A").get("flags", {}).get("has_shot", false):
	return "the unit was marked as having shot"
if sc.weapon_assignments.size() != 3 or sc.target_basket.item_count != 3 or sc.confirm_button.disabled:
	return "panel not rebuilt: %d assignments, %d target rows, confirm disabled=%s" % [sc.weapon_assignments.size(), sc.target_basket.item_count, sc.confirm_button.disabled]
var ws = GameState.get_unit("U_WITCHSEEKERS_C")
for m in ws.get("models", []):
	if not m.get("alive", true) or int(m.get("current_wounds", m.get("wounds", 1))) < int(m.get("wounds", 1)):
		return "a Witchseeker took damage — something was rolled"
if tree.root.get_node("Main")._settings_menu != null:
	return "Esc opened the settings menu instead"
return "ok"

