var d = sc.resolution_dock
var c = d.cancel_button
if not c.is_visible_in_tree() or not c.disabled:
	return "Back should be shown greyed out (visible=%s disabled=%s)" % [c.is_visible_in_tree(), c.disabled]
if not str(c.tooltip_text).contains("locked in") or not str(c.tooltip_text).contains("opponent"):
	return "tooltip does not say why: %s" % c.tooltip_text
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
if not d.is_ordering() or str(ph.resolution_state.get("phase", "")) != "awaiting_weapon_order":
	return "Esc cancelled a locked declaration"
if ph.confirmed_assignments.size() != 3 or not ph.pending_assignments.is_empty():
	return "declaration changed"
if not str(d.status_label.text).begins_with("Targets are locked in"):
	return "no explanation in the panel: %s" % d.status_label.text
if sc.active_shooter_id != "U_BATTLEWAGON_A":
	return "shooter deselected"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
var ph = PhaseManager.get_current_phase_instance()
if str(ph.resolution_state.get("mode", "")) != "sequential_staged":
	return "sequence not started: %s" % str(ph.resolution_state.get("mode", ""))
if (ph.resolution_state.get("weapon_order", []) as Array).size() != 3:
	return "weapon order not handed over"
if d.state != "staged_hits":
	return "dock not at the hit pause: %s" % d.state
if d.cancel_button.visible:
	return "Back still offered after the dice rolled"
return "ok"

var sc = tree.root.get_node("Main/ShootingController")
var d = sc.resolution_dock
if d.state != "staged_hits" or sc.active_shooter_id != "U_BATTLEWAGON_A":
	return "Esc mid-roll changed the activation (state %s, shooter %s)" % [d.state, sc.active_shooter_id]
if tree.root.get_node("Main")._settings_menu != null:
	return "settings menu opened"
return "ok"
